        self.board = board
        self.players = list(players)
        self.pos = {p: 0 for p in players}
        self.turn = 0
        self.winner = None

    def current(self):
        return self.players[self.turn]

    def move(self, roll):
        # TODO: move the current player, apply snakes and ladders, the exact-finish rule and the win.
        player = self.current()
        self._next_turn(roll)
        return f"{player} rolls {roll}"

    def _next_turn(self, roll):
        self.turn = (self.turn + 1) % len(self.players)

import sys

from game import Board, Game


def main():
    board, game = None, None
    for raw in sys.stdin:
        p = raw.split()
        if not p:
            continue
        if p[0] == "BOARD" and len(p) == 2 and board is None:
            board = Board(int(p[1]))
            print(f"board of {p[1]}")
        elif p[0] in ("SNAKE", "LADDER") and len(p) == 3 and board is not None and game is None:
            a, b = int(p[1]), int(p[2])
            ok = 0 < b < a < board.size if p[0] == "SNAKE" else 0 < a < b <= board.size
            if ok:
                board.add_jump(a, b)
                print(f"{p[0].lower()} {a} -> {b}")
            else:
                print(f"error: bad {p[0].lower()} {a} {b}")
        elif p[0] == "PLAYERS" and len(p) >= 2 and board is not None and game is None:
            game = Game(board, p[1:])
            print("players: " + " ".join(p[1:]))
        elif p[0] == "ROLL" and len(p) == 2 and game is not None and p[1] in "123456" and len(p[1]) == 1:
            print(f"game over: {game.winner} won" if game.winner else game.move(int(p[1])))
        else:
            print(f"error: bad command {raw.strip()}")


main()

