class Game:
    def __init__(self, board, players):
        self.board = board
        self.players = list(players)
        self.pos = {p: 0 for p in players}
        self.turn = 0
        self.winner = None

    def current(self):
        return self.players[self.turn]

    def move(self, roll):
        player = self.current()
        start = self.pos[player]
        target = start + roll
        if target > self.board.size:
            note = f"{player} rolls {roll}, stays at {start}"
        else:
            end = self.board.land(target)
            kind = "" if end == target else (" (ladder)" if end > target else " (snake)")
            self.pos[player] = end
            note = f"{player} rolls {roll}, {start} -> {end}{kind}"
            if end == self.board.size:
                self.winner = player
                return note + f"\n{player} wins"
        self._next_turn(roll)
        return note

    def _next_turn(self, roll):
        self.turn = (self.turn + 1) % len(self.players)

