import java.util.*;

class Board {
    final int size;
    final Map<Integer, Integer> jumps = new HashMap<>();
    Board(int size) { this.size = size; }
    void addJump(int start, int end) { jumps.put(start, end); }
    int land(int square) { return jumps.getOrDefault(square, square); }
}

class Game {
    final Board board;
    final List<String> players;
    final Map<String, Integer> pos = new HashMap<>();
    int turn = 0;
    String winner = null;

    Game(Board board, List<String> players) {
        this.board = board;
        this.players = players;
        for (String p : players) pos.put(p, 0);
    }

    String move(int roll) {
        // TODO: move the current player, apply snakes and ladders, the exact-finish rule and the win.
        String player = players.get(turn);
        nextTurn(roll);
        return player + " rolls " + roll;
    }

    void nextTurn(int roll) {
        turn = (turn + 1) % players.size();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();
        Board board = null;
        Game game = null;
        for (String raw; (raw = in.readLine()) != null; ) {
            String[] p = raw.trim().split("\\s+");
            if (p[0].isEmpty()) continue;
            String reply;
            if (p[0].equals("BOARD") && p.length == 2 && board == null) {
                board = new Board(Integer.parseInt(p[1]));
                reply = "board of " + p[1];
            } else if ((p[0].equals("SNAKE") || p[0].equals("LADDER")) && p.length == 3 && board != null && game == null) {
                int a = Integer.parseInt(p[1]), b = Integer.parseInt(p[2]);
                boolean ok = p[0].equals("SNAKE") ? (0 < b && b < a && a < board.size) : (0 < a && a < b && b <= board.size);
                String kind = p[0].toLowerCase();
                if (ok) { board.addJump(a, b); reply = kind + " " + a + " -> " + b; }
                else reply = "error: bad " + kind + " " + a + " " + b;
            } else if (p[0].equals("PLAYERS") && p.length >= 2 && board != null && game == null) {
                game = new Game(board, Arrays.asList(p).subList(1, p.length));
                reply = "players: " + String.join(" ", Arrays.asList(p).subList(1, p.length));
            } else if (p[0].equals("ROLL") && p.length == 2 && game != null && p[1].matches("[1-6]")) {
                reply = game.winner != null ? "game over: " + game.winner + " won" : game.move(Integer.parseInt(p[1]));
            } else reply = "error: bad command " + raw.trim();
            out.append(reply).append('\n');
        }
        System.out.print(out);
    }
}

