    final Map<Integer, Integer> jumps = new HashMap<>();
    Board(int size) { this.size = size; }
    void addJump(int start, int end) { jumps.put(start, end); }
    int land(int square) { return jumps.getOrDefault(square, square); }
}

class Game {
    final Board board;
    final List<String> players;
    final Map<String, Integer> pos = new HashMap<>();
    int turn = 0;
    String winner = null;

    Game(Board board, List<String> players) {
        this.board = board;
        this.players = players;
        for (String p : players) pos.put(p, 0);
    }

    String move(int roll) {
        String player = players.get(turn);
        int start = pos.get(player), target = start + roll;
        String note;
        if (target > board.size) {
            note = player + " rolls " + roll + ", stays at " + start;
        } else {
            int end = board.land(target);
            String kind = end == target ? "" : (end > target ? " (ladder)" : " (snake)");
            pos.put(player, end);
            note = player + " rolls " + roll + ", " + start + " -> " + end + kind;
            if (end == board.size) {
                winner = player;
                return note + "\n" + player + " wins";
            }
        }
        nextTurn(roll);
        return note;
    }

    void nextTurn(int roll) {
        turn = (turn + 1) % players.size();
    }
}

